import React, { useState, useEffect } from 'react';
import { getLatestReadings, getSensorStats, getRecentAlerts, getAlertStats } from '../api/api';

function Dashboard() {
  // State for all the data
  const [readings, setReadings] = useState([]);
  const [sensorStats, setSensorStats] = useState(null);
  const [alerts, setAlerts] = useState([]);
  const [alertStats, setAlertStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Function to load data
  const getData = async () => {
    try {
      // Beginners usually call APIs one by one
      const res1 = await getLatestReadings();
      setReadings(res1.data);

      const res2 = await getSensorStats();
      setSensorStats(res2);

      const res3 = await getRecentAlerts(5);
      setAlerts(res3.data);

      const res4 = await getAlertStats();
      setAlertStats(res4);

      setLoading(false);
    } catch (err) {
      setError("Could not get data from the server");
      setLoading(false);
    }
  };

  useEffect(() => {
    getData();
    // Refresh every 30 seconds
    const myInterval = setInterval(() => {
      getData();
    }, 30000);

    return () => clearInterval(myInterval);
  }, []);

  if (loading == true) {
    return <div style={{ padding: '20px' }}>Loading...</div>;
  }

  return (
    <div style={{ padding: '20px' }}>
      <h1>Dashboard Overview</h1>
      <p>Live sensor monitoring</p>
      <button onClick={getData}>Refresh Now</button>

      {/* Statistics section */}
      <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
        <div style={{ border: '1px solid blue', padding: '10px', width: '200px' }}>
          <div>Total Readings</div>
          <div style={{ fontSize: '24px' }}>{sensorStats ? sensorStats.total_readings : 0}</div>
        </div>
        <div style={{ border: '1px solid green', padding: '10px', width: '200px' }}>
          <div>Active Devices</div>
          <div style={{ fontSize: '24px' }}>{sensorStats ? sensorStats.total_topics : 0}</div>
        </div>
        <div style={{ border: '1px solid red', padding: '10px', width: '200px' }}>
          <div>Total Alerts</div>
          <div style={{ fontSize: '24px' }}>{alertStats ? alertStats.total_alerts : 0}</div>
        </div>
      </div>

      {/* Sensor Grid */}
      <h2 style={{ marginTop: '30px' }}>Latest Sensor Readings</h2>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
        {readings.map((r) => (
          <div key={r.id} style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px', minWidth: '250px' }}>
            <div style={{ fontWeight: 'bold' }}>{r.topic}</div>
            <div style={{ fontSize: '12px', color: 'gray' }}>Time: {new Date(r.received_at).toLocaleString()}</div>
            <hr />
            {/* Beginners often write out every condition manually */}
            {r.temperature != null && <div>🌡️ Temp: {r.temperature} °C</div>}
            {r.humidity != null && <div>💧 Humidity: {r.humidity} %</div>}
            {r.voltage != null && <div>⚡ Voltage: {r.voltage} V</div>}
            {r.current != null && <div>🔌 Current: {r.current} A</div>}
          </div>
        ))}
      </div>

      {/* Recent Alerts */}
      <h2 style={{ marginTop: '30px' }}>Recent Alerts</h2>
      <div style={{ background: '#f9f9f9', padding: '10px' }}>
        {alerts.length == 0 ? (
          <p>No alerts yet!</p>
        ) : (
          alerts.map((a) => (
            <div key={a.id} style={{ marginBottom: '10px', padding: '10px', borderLeft: '5px solid red', background: 'white' }}>
              <strong>📍 {a.topic}</strong> - {a.severity}
              <div>Issues: {a.violated_keys.join(", ")}</div>
              <div style={{ fontSize: '11px' }}>{new Date(a.created_at).toLocaleString()}</div>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Dashboard;
